    "question": "I- Pankreastan insülin salınımını uyarır ve insüline direnci artırır.\nII- Böbrek tübüllerinden sodyum ve klorun emilimini ve böylece suyun tutulmasını artırır (Ödem).\nIII- Yağ dokudaki endojen lipazı etkinleştirerek yağların yıkımlanmasını ve sonuçta serbest trigliserit ve yağ asitleri düzeyini artırır, sonuçta keton cisimleri oluşarak ketozis meydana gelir.\nIV- Deride esmerleşme meydana gelir.\nV- Kalp kasının kasılım gücünü artırır (pozitif inotrop etki).\nVI- Kandaki eozinofil ve lenfositlerin sayısını azaltır.\nYukarıda bazı fonksiyonları verilen hormon aşağıdakilerden hangisidir?",
