    "explanation": "Doğru Seçenek: B) Meme başında çok katlı yassı epitel, ana duktuslarda iki katlı kübik/prizmatik epitel, terminal kanallarda tek katlı kübik/prizmatik epitel. Laktiferöz kanallar meme başı porusunda epidermisin devamı olan çok katlı yassı epitelle döşelidir. Sinus lactiferus ve ana duktuslarda iki katlı kübik/kolumnar epitele, terminal duktuslarda ise tek katlı kübik/prizmatik epitele dönüşür.",
