    "open_answer": "1. Fenestrasyonlu Endotel (Glomerül kapiller endoteli) Glomerül Bazal Membranı (GBM): Lamina rara interna Lamina densa (Kollajen Tip 4 ve lamininden zengin ana süzgeç) Lamina rara externa Podosit Ayakları (Pedisel) ve aralarındaki filtrasyon yarıkları (Slit diyafram).",
    "explanation": "Doğru Seçenek: C) Fenestrasyonlu endotel — Glomerül bazal membranı (Lamina rara interna, Lamina densa, Lamina rara externa) — Podosit pediselleri. Filtrasyon bariyeri içten dışa sırasıyla: 1) Fenestrasyonlu glomerül kapiller endoteli, 2) Glomerül bazal membranı (lamina rara interna, lamina densa ve lamina rara externa), 3) Podositlerin pediselleri ve aralarındaki slit diyaframıdır.",
