    "explanation": "Doğru Seçenek: D) Korteks: Mezoderm (Sölom epiteli) — Medulla: Nöroektoderm (Krista nöralis). Adrenal korteks arka karın duvarındaki sölom mezoderminden gelişir. Adrenal medulla ise modifiye sempatik postganglionik nöronlar olan kromaffin hücrelerini oluşturmak üzere göç eden nöral krista (krista nöralis) hücrelerinden gelişir.",
