    "answer": "C",
    "open_answer": "Growth Hormon (GH - Büyüme Hormonu) ve Prolaktin.",
    "explanation": "Doğru Seçenek: C) Büyüme Hormonu (GH) ve Prolaktin. Büyüme hormonu (GH), prolaktin ve eritropoietin hücre yüzeyindeki sitokin reseptör süperailesi üyelerine bağlanır. İntrensek kinaz aktivitesi olmayan bu reseptörler sitoplazmik tirozin kinaz olan JAK'ı aktive eder, JAK da STAT proteinlerini fosforilleyerek çekirdeğe gönderir.",
