    "open_answer": "Santral Diabetes Insipidus (Şekersiz Şeker Hastalığı) \\implies Dilüe (aşırı sulu, düşük osmolaliteli) idrar çıkışı ve poliüri.",
    "explanation": "Doğru Seçenek: E) Santral Diabetes Insipidus — Dilüe (düşük osmolaliteli/dansiteli) poliüri. ADH eksikliğinde toplayıcı kanallarda su geri emilemez ve Santral Diabetes Insipidus gelişir. Hasta günde 10-15 litreyi aşan çok sulu, dilüe (dansitesi <1.005, düşük osmolaliteli) idrar çıkarır (poliüri ve kompansatris polidipsi).",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
