    "open_answer": "t(9;22)(q34;q11) translokasyonu sonucu oluşan anormal 22. kromozomdur. KML (Kronik Myeloid Lösemi) için karakteristiktir. BCR-ABL füzyon geni oluşur ve bu gen sürekli aktif bir tirozin kinaz üreterek hücre çoğalmasını tetikler.",
    "explanation": "Doğru Seçenek: B) t(9;22)(q34;q11) resiprokal translokasyonu — BCR-ABL1 füzyon geni. Philadelphia kromozomu [t(9;22)(q34;q11)], 9. kromozomdaki ABL1 tirozin kinaz geni ile 22. kromozomdaki BCR geninin birleşmesiyle oluşur. Sürekli aktif tirozin kinaz üreterek kontrolsüz granülosit proliferasyonuna ve KML tablosuna yol açar.",
